import {
	digest,
	type NormalizedSnapshot,
} from "../../server/services/local-session-detach/contract";

/** Opaque identities only: never connect these labels to production DB rows or host paths. */
export function ordinaryDetachFixture(): NormalizedSnapshot {
	const workspaceContext = JSON.stringify({
		revision: 4,
		deviceId: "fixture:local",
		cwd: "fixture:path",
		pathFlavor: "posix",
		contextKey: "fixture:context",
		contextProjectId: "fixture:project",
		git: { workspaceKey: "fixture:path", repositoryKey: "fixture:repo", rootPath: "fixture:path" },
		capabilities: { switchDirectory: true },
	});
	return {
		format: "local-session-detach-fixture/v1",
		namespace: "fixture:test",
		instance: "fixture:instance",
		schema: "fixture-schema-v1",
		collection: {
			complete: true,
			currentSnapshot: true,
			pages: 1,
			missingObjects: [],
			truncated: false,
		},
		narrator: {
			id: "fixture:narrator",
			chapterId: "fixture:chapter",
			contextProjectId: "fixture:project",
			cwd: "fixture:path",
			defaultDeviceId: null,
			workspaceContext,
			workspaceRevision: 4,
			messageVersion: 7,
			messageStructureVersion: 3,
			type: "primary",
			variant: "primary",
			status: "idle",
			traits: "[]",
			isAskInPassing: false,
			isBackground: false,
			ownerUserId: "fixture:user",
			oauthOwnerGrantId: null,
			oauthPolicySnapshotJson: null,
			forkMessageId: "fixture:message",
			parentNarratorId: "fixture:parent",
			refsInherited: true,
			lazyWindow: '{ "start": 2 }',
			permissionMode: "default",
			readOnly: false,
			denyRules: '[ "delete" ]',
			audience: '["private"]',
			rawBusinessJson: '{"z":1, "a": 2}',
			opaqueBlob: { blobBase64: "AP9h" },
		},
		chapter: {
			id: "fixture:chapter",
			projectId: "fixture:project",
			state: "active",
			role: "branch",
			snapshotShadowKey: "fixture:shadow",
			dormantAt: null,
			mergedIntoChapterId: null,
		},
		identity: {
			deviceId: "fixture:local",
			path: "fixture:path",
			cwd: "fixture:path",
			worktree: "fixture:path",
			repositoryKey: "fixture:repo",
			cwdRepositoryKey: "fixture:repo",
			directoryIdentity: "fixture:inode-1",
			symlinkIdentity: "fixture:symlink-1",
			shadowKey: "fixture:shadow",
			treeBoundaryPath: "fixture:path",
			local: true,
			known: true,
		},
		acl: {
			rootId: "fixture:acl",
			projectId: "fixture:project",
			ownerUserId: "fixture:user",
			ownerExists: true,
			ownerNarratorIds: ["fixture:narrator"],
			shared: false,
			source: "local",
			permissionLineage: [
				{ id: "fixture:permission", rootId: "fixture:acl", denyRules: '[ "delete" ]' },
			],
			readOnly: false,
			denyRulesKnown: true,
			lineageComplete: true,
		},
		authority: {
			actorId: "fixture:user",
			exists: true,
			canDetach: true,
			admin: false,
			revision: 1,
			policyFingerprint: digest("fixture:current-actor-policy"),
		},
		runtime: {
			ownerEpoch: 1,
			generation: 3,
			fence: 5,
			leaseVersion: 2,
			leaseId: null,
			leases: [],
			quarantined: false,
			paused: false,
			state: "idle",
			queues: [],
			activeChildren: [],
			waitingPermissions: [],
			observationsComplete: true,
		},
		resource: {
			id: "fixture:resource",
			row: null,
			claims: [],
			uses: [],
			evidenceComplete: true,
			dependencies: [],
		},
		closure: {
			complete: true,
			historicalPathsKnown: true,
			rootIds: ["fixture:history"],
			objects: (
				["history", "lazy", "ref", "tool", "spec", "provenance", "blob", "tree"] as const
			).map((kind) => {
				const bytes = Buffer.from(`{ "kind": "${kind}", "unicode": "中文" }\n`);
				return {
					id: `fixture:${kind}`,
					kind,
					row: { id: `fixture:${kind}`, rawJson: bytes.toString(), binary: { blobBase64: "AP8=" } },
					rawBase64: bytes.toString("base64"),
					byteDigest: digest(bytes),
					dependencies:
						kind === "history"
							? [
									"fixture:ref",
									"fixture:lazy",
									"fixture:tool",
									"fixture:spec",
									"fixture:provenance",
									"fixture:blob",
									"fixture:tree",
								]
							: [],
					available: true,
				};
			}),
		},
		beforeRows: [
			{ table: "fixture:spec-store", id: "fixture:spec-root", row: { text: "原始 spec\r\n" } },
			{ table: "fixture:metadata", id: "fixture:missing", row: null },
		],
	};
}
